description:
Implement a `useEffectOnce` hook that runs an effect exactly once on mount. If the effect returns a cleanup function, that cleanup must be called on unmount. The effect must NOT re-run on rerenders.

**Example:**
```tsx
useEffectOnce(() => {
  analytics.track('page_view');
  return () => analytics.flush();
});
```

starter_code:
import { useEffect } from 'react';

export function useEffectOnce(effect: () => void | (() => void)): void {
  // your code here
}

test_suite:
test('effect fires on mount', () => {
  const effect = vi.fn();
  renderHook(() => useEffectOnce(effect));
  expect(effect).toHaveBeenCalledTimes(1);
});

test('effect does NOT fire on rerender', () => {
  const effect = vi.fn();
  const { rerender } = renderHook(() => useEffectOnce(effect));
  rerender();
  rerender();
  expect(effect).toHaveBeenCalledTimes(1);
});

test('cleanup fires on unmount', () => {
  const cleanup = vi.fn();
  const { unmount } = renderHook(() => useEffectOnce(() => cleanup));
  unmount();
  expect(cleanup).toHaveBeenCalledTimes(1);
});

// __hidden__
test('cleanup does NOT fire on rerender', () => {
  const cleanup = vi.fn();
  const { rerender } = renderHook(() => useEffectOnce(() => cleanup));
  rerender();
  rerender();
  expect(cleanup).not.toHaveBeenCalled();
});

solution:
import { useEffect } from 'react';

export function useEffectOnce(effect: () => void | (() => void)): void {
  useEffect(effect, []);
}
